1	/*
2	 * Copyright (c) 2023, Salesforce, Inc.
3	 * All rights reserved.
4	 * SPDX-License-Identifier: BSD-3-Clause
5	 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
6	 */
7	
8	/*
9	 * Copy-first port of
10	 * node_modules/@salesforce/retail-react-app/app/components/product-view/index.jsx
11	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
12	 *
13	 * Apart from the one added prop described in the next paragraph, the differences from the base
14	 * file are the TypeScript annotations below, house formatting, and a small number of
15	 * optional-chaining guards that strictNullChecks requires — each flagged in place with a
16	 * `Deviation from the base file` comment.
17	 *
18	 * Per the SFCC bridge pattern in .claude/rules/overrideStyling.md, the default export stays a
19	 * faithful port with the same `forwardRef` behaviour. It carries exactly one additive optional
20	 * prop over the base file's surface — `renderHeader`, documented on `ProductViewProps` below.
21	 * It is behaviour-preserving when omitted (its default renders the same private
22	 * `ProductViewHeader` the base file renders inline), and `renderHeader` has zero occurrences in
23	 * the base package, so none of the four base modules that import ProductView — product-view-modal
24	 * (index and bundle), bonus-product-view-modal, and pages/product-detail — passes it or is
25	 * affected by it. (The runtime `propTypes` blocks are replaced by the TypeScript prop types; see
26	 * the note at the foot of the file.)
27	 */
28	
29	import React, { forwardRef, useEffect, useMemo, useRef, useState, useCallback } from 'react';
30	import { useLocation } from 'react-router-dom';
31	import { useIntl, FormattedMessage } from 'react-intl';
32	
33	import {
34	  Flex,
35	  Heading,
36	  Button,
37	  Skeleton,
38	  Box,
39	  Text,
40	  VStack,
41	  Fade,
42	  Stack,
43	  Radio,
44	  RadioGroup,
45	  useTheme,
46	} from '@salesforce/retail-react-app/app/components/shared/ui';
47	
48	// Constants
49	const DELIVERY_OPTIONS = {
50	  DELIVERY: 'delivery',
51	  PICKUP: 'pickup',
52	};
53	import { useCurrency, useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
54	import { useAddToCartModalContext } from '@salesforce/retail-react-app/app/hooks/use-add-to-cart-modal';
55	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
56	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
57	import { useShopperBasketsV2Mutation as useShopperBasketsMutation } from '@salesforce/commerce-sdk-react';
58	import { useSFPayments, useExpressCheckoutEnabled } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
59	
60	// project components
61	import ImageGallery from '@salesforce/retail-react-app/app/components/image-gallery';
62	import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
63	import Link from '@salesforce/retail-react-app/app/components/link';
64	import withRegistration from '@salesforce/retail-react-app/app/components/with-registration';
65	import { Skeleton as ImageGallerySkeleton } from '@salesforce/retail-react-app/app/components/image-gallery';
66	import { HideOnDesktop, HideOnMobile } from '@salesforce/retail-react-app/app/components/responsive';
67	import QuantityPicker from '@salesforce/retail-react-app/app/components/quantity-picker';
68	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
69	import { API_ERROR_MESSAGE } from '@salesforce/retail-react-app/app/constants';
70	import DisplayPrice from '@salesforce/retail-react-app/app/components/display-price';
71	import Swatch from '@salesforce/retail-react-app/app/components/swatch-group/swatch';
72	import SwatchGroup from '@salesforce/retail-react-app/app/components/swatch-group';
73	import { getPriceData } from '@salesforce/retail-react-app/app/utils/product-utils';
74	import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';
75	import SFPaymentsExpressButtons from '@salesforce/retail-react-app/app/components/sf-payments-express-buttons';
76	import { EXPRESS_BUY_NOW } from '@salesforce/retail-react-app/app/hooks/use-sf-payments';
77	import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
78	import { useCleanupTemporaryBaskets } from '@salesforce/retail-react-app/app/hooks/use-cleanup-temporary-baskets';
79	
80	
81	/*
82	 * These are a deliberate temporary gap, NOT evidence that no type exists — do not read them
83	 * that way. `@salesforce/retail-react-app` ships no TypeScript types (see
84	 * overrides/app/types/vendor.d.ts), but the shapes underneath are `commerce-sdk-isomorphic`'s
85	 * and it does export them: `ShopperProductsTypes.Product` / `.Variant` / `.Category`, and
86	 * `.Image` for `image` below. AGENTS.md's Type Definitions rule says to import those directly.
87	 *
88	 * Substituting them is a follow-up rather than part of this PR only because it also removes
89	 * three `no-explicit-any` warnings, moving a lint count this branch holds as an invariant
90	 * across every commit.
91	 */
92	type SfccProduct = any;
93	type SfccVariant = any;
94	type SfccCategory = any;
95	type SfccPriceData = any;
96	
97	/** One selectable value of a variation attribute, as the base hooks shape it. */
98	type SfccVariationValue = { href?: string; name: string; image?: SfccProduct; value?: string; orderable?: boolean };
99	
100	/** A variation attribute (colour, size, ...) with its selectable values. */
101	type SfccVariationAttribute = {
102	  id: string;
103	  name?: string;
104	  selectedValue?: SfccVariationValue;
105	  values: SfccVariationValue[];
106	};
107	
108	/** SFCC variation attribute ID for the colour attribute — used to skip/filter it from the default swatch group. */
109	export const SFCC_COLOUR_ATTRIBUTE_ID = 'color';
110	
111	/** The per-child orderability record ProductView writes back to its parent. */
112	export type ChildProductOrderability = {
113	  showInventoryMessage?: boolean;
114	  unfulfillable?: boolean;
115	  isOutOfStock?: boolean;
116	  stockLevel?: number;
117	  productName?: string;
118	};
119	
120	export type ProductViewHeaderProps = {
121	  name?: string;
122	  currency?: string;
123	  priceData?: SfccPriceData;
124	  category?: SfccCategory[];
125	  product?: SfccProduct;
126	  isProductPartOfBundle?: boolean;
127	};
128	
129	/*
130	 * Mirrors the base file's `ProductView.propTypes` one-for-one, with the defaults declared in
131	 * the destructuring below reflected as optional. `validateOrderability`'s signature is taken
132	 * from the default implementation the base file supplies.
133	 */
134	type ProductViewProps = {
135	  product?: SfccProduct;
136	  category?: SfccCategory[];
137	  showFullLink?: boolean;
138	  imageSize?: 'sm' | 'md';
139	  isWishlistLoading?: boolean;
140	  addToCart?: ((productSelectionValues: SfccProduct[]) => unknown) | null;
141	  updateCart?: ((variant: SfccVariant, quantity: number) => unknown) | null;
142	  addToWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
143	  updateWishlist?: ((product: SfccProduct, variant: SfccVariant, quantity: number) => unknown) | null;
144	  isProductLoading?: boolean;
145	  isProductPartOfSet?: boolean;
146	  isProductPartOfBundle?: boolean;
147	  childOfBundleQuantity?: number;
148	  childProductOrderability?: Record<string, ChildProductOrderability>;
149	  setChildProductOrderability?: React.Dispatch<React.SetStateAction<Record<string, ChildProductOrderability>>>;
150	  isBasketLoading?: boolean;
151	  onVariantSelected?: (product: SfccProduct, variant: SfccVariant, quantity: number) => void;
152	  validateOrderability?: (
153	    variant: SfccVariant,
154	    product: SfccProduct,
155	    quantity: number,
156	    stockLevel: number,
157	  ) => boolean | undefined;
158	  showImageGallery?: boolean;
159	  setSelectedBundleQuantity?: (quantity: number) => void;
160	  selectedBundleParentQuantity?: number;
161	  pickupInStore?: boolean;
162	  setPickupInStore?: (checked: boolean) => void;
163	  onOpenStoreLocator?: () => void;
164	  showDeliveryOptions?: boolean;
165	  customButtons?: React.ReactElement[];
166	  promotionId?: string;
167	  maxOrderQuantity?: number | null;
168	  imageGalleryFooter?: React.ReactNode;
169	  alignItems?: string;
170	  controlledVariationValues?: Record<string, string> | null;
171	  onVariationChange?: ((attributeId: string, value: string) => void) | null;
172	  /**
173	   * The one Zimmermann addition to this component's prop surface. Replaces the header block
174	   * (breadcrumb, title, price, promo callout) with caller-supplied content, receiving exactly
175	   * the values the private `ProductViewHeader` is given so a caller can reuse or ignore any of
176	   * them. Defaults to rendering that same private header, so every existing caller — cart,
177	   * wishlist, bonus-product — is byte-identical unless it opts in.
178	   *
179	   * ProductView renders the header twice (mobile and desktop breakpoints), so this is called
180	   * twice with the same arguments. Keep it pure.
181	   */
182	  renderHeader?: (props: ProductViewHeaderProps) => React.ReactNode;
183	  /**
184	   * When true, the colour variation attribute is skipped in the default swatch group.
185	   * Use only when the caller provides its own colour UI (e.g. PDP ColourSwatches via afterContent).
186	   * Non-PDP callers (cart, wishlist, bonus-product) must leave this unset so colour selection
187	   * continues to work through the standard SwatchGroup.
188	   */
189	  suppressColourAttribute?: boolean;
190	};
191	
192	/*
193	 * The base file rebinds a function ref's `this` so the parent can reach `validateOrderability`
194	 * (see the `typeof ref === 'function'` branch below, and the set/bundle child refs in
195	 * pages/product-detail).
196	 */
197	type ProductViewRef = React.ForwardedRef<HTMLDivElement>;
198	
199	/**
200	 * The scope ProductView rebinds onto a callback `ref`, so a parent rendering set/bundle
201	 * children can reach this instance's validation. See the `typeof ref === 'function'` branch
202	 * below. A consumer names it as the `this` parameter of its ref callback —
203	 * `function (this: ProductViewRefScope, ref) { ... }` — which TypeScript accepts as a `ref`
204	 * as written; no assertion is required at the prop site.
205	 */
206	export type ProductViewRefScope = {
207	  validateOrderability: (opts: { scrollErrorIntoView: boolean }) => void;
208	};
209	
210	const ProductViewHeader = ({
211	  name,
212	  currency,
213	  priceData,
214	  category,
215	  product,
216	  isProductPartOfBundle,
217	}: ProductViewHeaderProps) => {
218	  return (
219	    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
220	      {category && (
221	        <Skeleton isLoaded={category} minWidth={64}>
222	          <Breadcrumb categories={category} />
223	        </Skeleton>
224	      )}
225	
226	      {/* Title */}
227	      <Skeleton isLoaded={name}>
228	        <Heading fontSize="2xl">{`${name}`}</Heading>
229	      </Skeleton>
230	
231	      {!isProductPartOfBundle && (
232	        <>
233	          <Skeleton isLoaded={priceData?.currentPrice}>
234	            {priceData?.currentPrice && <DisplayPrice priceData={priceData} currency={currency} />}
235	          </Skeleton>
236	
237	          <Skeleton isLoaded={product}>{product?.productPromotions && <PromoCallout product={product} />}</Skeleton>
238	        </>
239	      )}
240	    </VStack>
241	  );
242	};
243	
244	const ButtonWithRegistration = withRegistration(Button);
245	
246	/**
247	 * Render a product detail view that includes name, image gallery, price,
248	 * variant selections, action buttons
249	 */
250	
251	const ProductView = forwardRef(
252	  (
253	    {
254	      product,
255	      category,
256	      showFullLink = false,
257	      imageSize = 'md',
258	      isWishlistLoading = false,
259	      addToCart,
260	      updateCart,
261	      addToWishlist,
262	      updateWishlist,
263	      isProductLoading,
264	      isProductPartOfSet = false,
265	      isProductPartOfBundle = false,
266	      childOfBundleQuantity = 0,
267	      childProductOrderability,
268	      setChildProductOrderability,
269	      isBasketLoading = false,
270	      onVariantSelected = () => {},
271	      validateOrderability = (variant, product, quantity, stockLevel) => {
272	        if (isProductLoading) return false;
273	
274	        // If product has variations, a variant must be selected
275	        if (product?.variationAttributes?.length > 0 && !variant) {
276	          return false;
277	        }
278	
279	        // Check if product (either variant or standard) is orderable and if quantity is valid
280	        return (variant?.orderable || product?.inventory?.orderable) && quantity > 0 && quantity <= stockLevel;
281	      },
282	      showImageGallery = true,
283	      setSelectedBundleQuantity = () => {},
284	      selectedBundleParentQuantity = 1,
285	      pickupInStore = false,
286	      setPickupInStore = () => {},
287	      onOpenStoreLocator = () => {},
288	      showDeliveryOptions = true,
289	      customButtons = [],
290	      maxOrderQuantity = null,
291	      imageGalleryFooter = null,
292	      controlledVariationValues = null,
293	      onVariationChange = null,
294	      renderHeader = (headerProps: ProductViewHeaderProps) => <ProductViewHeader {...headerProps} />,
295	      suppressColourAttribute = false,
296	    }: ProductViewProps,
297	    ref: ProductViewRef,
298	  ) => {
299	    const { currency: activeCurrency } = useCurrency();
300	    const showToast = useToast();
301	    const intl = useIntl();
302	    const location = useLocation();
303	    const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
304	    const {
305	      isOpen: isAddToCartModalOpen,
306	      onOpen: onAddToCartModalOpen,
307	      onClose: onAddToCartModalClose,
308	    } = useAddToCartModalContext();
309	
310	    const { mutateAsync: createBasket } = useShopperBasketsMutation('createBasket');
311	    const { mutateAsync: addItemToBasket } = useShopperBasketsMutation('addItemToBasket');
312	
313	    const theme = useTheme();
314	    const { confirmingBasket } = useSFPayments();
315	    const [showOptionsMessage, toggleShowOptionsMessage] = useState(false);
316	    const {
317	      showLoading,
318	      showInventoryMessage,
319	      inventoryMessage,
320	      quantity,
321	      minOrderQuantity,
322	      setQuantity,
323	      variant,
324	      variationParams,
325	      variationAttributes,
326	      stockLevel,
327	      stepQuantity,
328	      isOutOfStock,
