965	                              defaultMessage="Ship to Address"
966	                              id="product_view.label.ship_to_address"
967	                            />
968	                          </Radio>
969	                          {storeLocatorEnabled && (
970	                            <Radio
971	                              value={DELIVERY_OPTIONS.PICKUP}
972	                              isDisabled={!pickupEnabled || (storeName && inventoryId && isSelectedStoreOutOfStock)}
973	                            >
974	                              <FormattedMessage
975	                                defaultMessage="Pick Up in Store"
976	                                id="product_view.label.pickup_in_store"
977	                              />
978	                            </Radio>
979	                          )}
980	                        </Stack>
981	                      </RadioGroup>
982	                    </Box>
983	
984	                    {storeLocatorEnabled && (
985	                      <>
986	                        {storeName && inventoryId && (
987	                          <Text color="black" fontWeight={600} mb={2} data-testid="store-stock-status-msg">
988	                            {!isSelectedStoreOutOfStock
989	                              ? intl.formatMessage(
990	                                  {
991	                                    id: 'product_view.status.in_stock_at_store',
992	                                    defaultMessage: 'In stock at {storeName}',
993	                                  },
994	                                  {
995	                                    storeName: (
996	                                      <Link
997	                                        as="button"
998	                                        color="blue.600"
999	                                        textDecoration="underline"
1000	                                        onClick={onOpenStoreLocator}
1001	                                      >
1002	                                        {storeName}
1003	                                      </Link>
1004	                                    ),
1005	                                  },
1006	                                )
1007	                              : intl.formatMessage(
1008	                                  {
1009	                                    id: 'product_view.status.out_of_stock_at_store',
1010	                                    defaultMessage: 'Out of Stock at {storeName}',
1011	                                  },
1012	                                  {
1013	                                    storeName: (
1014	                                      <Link
1015	                                        as="button"
1016	                                        color="blue.600"
1017	                                        textDecoration="underline"
1018	                                        onClick={onOpenStoreLocator}
1019	                                      >
1020	                                        {storeName}
1021	                                      </Link>
1022	                                    ),
1023	                                  },
1024	                                )}
1025	                          </Text>
1026	                        )}
1027	
1028	                        {/* Show label if pickup is disabled due to no store/inventoryId */}
1029	                        {!pickupEnabled && !storeName && !inventoryId && (
1030	                          <Text color="black" fontWeight={600} mb={3} data-testid="pickup-select-store-msg">
1031	                            <FormattedMessage
1032	                              defaultMessage="Pick up in "
1033	                              id="product_view.label.pickup_in_select_store_prefix"
1034	                            />{' '}
1035	                            <Link as="button" color="blue.600" textDecoration="underline" onClick={onOpenStoreLocator}>
1036	                              <FormattedMessage
1037	                                defaultMessage="Select Store"
1038	                                id="product_view.label.select_store_link"
1039	                              />
1040	                            </Link>
1041	                          </Text>
1042	                        )}
1043	                      </>
1044	                    )}
1045	                  </>
1046	                )}
1047	                <Box display={isProductPartOfSet ? 'block' : ['none', 'none', 'none', 'block']}>
1048	                  {renderActionButtons()}
1049	                </Box>
1050	              </Box>
1051	            </Box>
1052	          </VStack>
1053	        </Flex>
1054	
1055	        {/* Sticky call-to-action buttons for mobile and certain product types */}
1056	        <Box
1057	          position="fixed"
1058	          bg="white"
1059	          width="100%"
1060	          display={isProductPartOfSet || isProductPartOfBundle ? 'none' : ['block', 'block', 'block', 'none']}
1061	          p={[4, 4, 6]}
1062	          left={0}
1063	          bottom={0}
1064	          zIndex={2}
1065	          boxShadow={theme.shadows.top}
1066	        >
1067	          {renderActionButtons()}
1068	        </Box>
1069	
1070	        {/* Loading overlay during express payment confirmation */}
1071	        {confirmingBasket && <LoadingSpinner wrapperStyles={{ height: '100vh' }} />}
1072	      </Flex>
1073	    );
1074	  },
1075	);
1076	
1077	ProductView.displayName = 'ProductView';
1078	
1079	/*
1080	 * The base file's `ProductViewHeader.propTypes` / `ProductView.propTypes` blocks are not
1081	 * carried over: the `ProductViewHeaderProps` / `ProductViewProps` types above express the
1082	 * same prop contract, and do so at compile time for every caller rather than as a dev-only
1083	 * runtime warning. Keeping both would duplicate the contract in two places that can drift.
1084	 */
1085	
1086	export default ProductView;
1087

