  <Fragment>
    <Island hydrateOn={'visible'}>
      <ProductView
        product={product}
        category={primaryCategory?.parentCategoryTree || []}
        suppressColourAttribute={hasOfferedColour}
        renderHeader={(headerProps) => (
          <StaticProductHeader
            {...headerProps}
            afterContent={
              hasOfferedColour ? (
                <ColourSwatches
                  variants={colourVariants}
                  selectedValue={selectedColour}
                  onSelect={handleColourSelect}
                />
              ) : undefined
            }
          />
        )}
        addToCart={handleAddToCart}
        addToWishlist={handleAddToWishlist}
