/**
 * Project-owned reimplementation of the SFCC base app's `filterImageGroups` utility.
 * Sourced from node_modules/@salesforce/retail-react-app/app/utils/product-utils.js
 * (retail-react-app 10.0.0) — that path is an internal module with no public export,
 * so we own the implementation here rather than importing across the stability boundary.
 */

type VariationAttribute = {
  id: string;
  values?: Array<{ value: string }>;
};

type ImageGroup = {
  viewType?: string;
  variationAttributes?: VariationAttribute[];
  images?: Array<Record<string, unknown>>;
};

type ImageGroupFilters = {
  viewType?: string;
  variationValues?: Record<string, string>;
};

export const filterImageGroups = (imageGroups: ImageGroup[] = [], filters: ImageGroupFilters): ImageGroup[] => {
  if (!filters) {
    throw new Error('Missing required "filters" argument');
  }

  const { viewType, variationValues = {} } = filters;
  const [selectedAttributeId, selectedAttributeValue] = Object.entries(variationValues)[0] ?? [];

  const typeFilter = viewType ? (group: ImageGroup) => group.viewType === viewType : () => true;
  const attributeFilter =
    selectedAttributeId && selectedAttributeValue
      ? ({ variationAttributes = [] }: ImageGroup) =>
          variationAttributes.some(
            ({ id, values }) =>
              id === selectedAttributeId && values?.some(({ value }) => value === selectedAttributeValue),
          )
      : () => true;

  return imageGroups.filter(typeFilter).filter(attributeFilter);
};

