// back/forward, or history.replace from another handler) or when the product changes while
// the component stays mounted. Without this, useState only captures the mount-time value.
useEffect(() => {
  setShopperSelectedColour(urlColour);
// eslint-disable-next-line react-hooks/exhaustive-deps
}, [urlColour, requestedProductId]);

// history.replace updates ?color= in the URL. useDerivedProduct inside ProductView reads
// URL params via usePDPSearchParams/useVariationParams on every location change, so this
// is the same mechanism as clicking a base swatch <a href="?color=value"> — no
// controlledVariationValues or onVariationChange needed (those are for bundle/child products).
const handleColourSelect = (value: string) => {
  setShopperSelectedColour(value);
  const params = new URLSearchParams(location.search);
  params.set(SFCC_COLOUR_ATTRIBUTE_ID, value);
  history.replace(`${location.pathname}?${params.toString()}`);
};

