  const colourAttr = productResponse?.variationAttributes?.find((attr: { id: string }) => attr.id === SFCC_COLOUR_ATTRIBUTE_ID);
  if (!colourAttr?.values) return [];
  return colourAttr.values.map((v: { value: string; name?: string; orderable?: boolean }) => {
    const groups = filterImageGroups(productResponse?.imageGroups ?? [], {
      viewType: 'swatch',
      variationValues: { [SFCC_COLOUR_ATTRIBUTE_ID]: v.value },
