// Swatch and control dimensions have no zimm foundation token — confirmed by designer.
// audit-allow: 188px, 47px, 72px, 24px, -2px — no swatch-dimension tokens exist yet
export const ZimmColourSwatches = {
  parts: [
    'container',
    'labelRow',
    'label',
    'selectedName',
    'paginationGroup',
    'chevronButton',
    'swatchGroup',
    'swatch',
    'swatchImage',
    'selectedIndicator',
  ],
  baseStyle: {
    container: {
      display: 'flex',
      flexDirection: 'column',
      gap: 'var(--zimm-scale-xs)',
      marginBottom: 'var(--zimm-scale-700)',
      // PAGE_SIZE (4) × swatch width (47px)
      width: '188px',
    },
    labelRow: {
      display: 'flex',
      alignItems: 'center',
      gap: 'var(--zimm-scale-2xs)',
    },
    label: {
      textStyle: 'caption',
      fontWeight: 'var(--zimm-font-weight-medium)',
      color: 'var(--zimm-color-text-default)',
      flexShrink: 0,
    },
    selectedName: {
      textStyle: 'caption',
      fontWeight: 'var(--zimm-font-weight-medium)',
      color: 'var(--zimm-color-text-default)',
      flex: '1 0 0',
      overflow: 'hidden',
      textOverflow: 'ellipsis',
      whiteSpace: 'nowrap',
    },
    paginationGroup: {
      display: 'flex',
      alignItems: 'center',
      flexShrink: 0,
    },
    chevronButton: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      // 24px hit area — no foundation token for swatch control dimensions
      width: '24px',
      height: '24px',
      background: 'transparent',
      border: 'none',
      cursor: 'pointer',
      color: 'var(--zimm-color-text-default)',
      '&:disabled': { opacity: 0.3, cursor: 'default' },
      '&:focus-visible': {
        outline: 'var(--zimm-focus-ring)',
        outlineOffset: 'var(--zimm-scale-3xs)',
      },
    },
    swatchGroup: {
      display: 'flex',
    },
    swatch: {
      position: 'relative',
      // 47px × 72px — no foundation token for swatch dimensions
      width: '47px',
      height: '72px',
      background: 'var(--zimm-color-bg-02)',
      border: 'none',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      cursor: 'pointer',
      outline: 'none',
      // Selected swatch must paint above siblings so the focus ring and indicator
      // are not clipped by the adjacent swatch rendered later in the DOM.
      '&:focus': { zIndex: 1 },
      // Focus ring: absolutely-positioned ::after overlay (Figma node 40002689-3839).
      // Asymmetric inset — bottom uses --zimm-focus-ring-offset-secondary (3px) negated
      // via calc() to clear the 1px selected-state border. The three 2px sides have no
      // foundation token; provisional: pending a dedicated --zimm-focus-ring-offset token.
      // `&:focus` not `&:focus-visible`: arrow-key programmatic focus doesn't reliably
      // trigger :focus-visible.
      '&:focus::after': {
        content: '""',
        position: 'absolute',
        // -2px has no zimm token (see comment above); -3px uses calc()
        inset: '-2px -2px calc(-1 * var(--zimm-focus-ring-offset-secondary)) -2px',
        border: 'var(--zimm-border-width-default) solid var(--zimm-color-border-focus)',
        pointerEvents: 'none',
      },
    },
    // mix-blend-multiply on the wrapper — makes white photo backgrounds transparent,
    // showing the ivory swatch bg through.
    swatchImage: {
      aspectRatio: '36 / 55',
      mixBlendMode: 'multiply',
      width: '100%',
    },
    // Selected indicator: absolutely-positioned bar at bottom of swatch.
    selectedIndicator: {
      position: 'absolute',
      bottom: 0,
      left: 0,
      right: 0,
      height: 'var(--zimm-border-width-default)',
      background: 'var(--zimm-color-border-focus)',
      pointerEvents: 'none',
    },
  },
};

