1	/*
2	 * SFCC-91 — PDP Colour Swatches & Variation Selection
3	 * Generated from e2e/features/pdp/SFCC-91_pdp-colour-swatches.feature (signed off 2026-08-20;
4	 * the non-orderable scenario was revised 2026-08-21 after the BA's AC5 clarification and
5	 * re-signed-off the same day).
6	 *
7	 * Every test skips until its fixture SKU is provisioned — see e2e/fixtures/products.js.
8	 * File extension is .js, not .ts: playwright.config.js pins `testMatch: '**\/*.spec.js'`,
9	 * so a .spec.ts here would be silently never discovered. See the spec doc for the open
10	 * Tier 1 question about widening discovery.
11	 */
12	
13	const { test, expect } = require('@playwright/test');
14	const { ProductPage } = require('../../../support/pages/ProductPage');
15	const {
16	  pdpProductWithMultipleColours,
17	  pdpProductWithUnpopulatedColour,
18	  pdpProductWithNonOrderableColour,
19	  pdpProductWithSingleColour,
20	  pdpProductWithAllColoursWithheld,
21	  standardProduct,
22	} = require('../../../fixtures/products');
23	
24	const TAGS = { tag: ['@pdp', '@SFCC-91'] };
25	
26	test.describe('PDP UI — Colour Swatches & Variation Selection', () => {
27	  test('A product with only one colour shows the colour name without swatches', TAGS, async ({ page }) => {
28	    const { sku } = pdpProductWithSingleColour();
29	    test.skip(!sku, 'No single-colour product SKU provisioned — set E2E_SINGLE_COLOUR_PRODUCT_SKU.');
30	
31	    const pdp = new ProductPage(page);
32	    await pdp.goToProduct(sku);
33	
34	    await expect(pdp.colourLabel).toBeVisible();
35	    await expect(pdp.colourSelectedName).not.toBeEmpty();
36	    // AC1 — the label names the colour, but there is nothing to choose between.
37	    await expect(pdp.colourSwatchGroup).toHaveCount(0);
38	  });
39	
40	  test('A product with multiple colours shows one swatch per colour', TAGS, async ({ page }) => {
41	    const { sku } = pdpProductWithMultipleColours();
42	    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');
43	
44	    const pdp = new ProductPage(page);
45	    await pdp.goToProduct(sku);
46	
47	    const colours = await pdp.offeredColourNames();
48	    expect(colours.length).toBeGreaterThanOrEqual(3);
49	    // Every swatch carries its own image — no empty placeholder boxes.
50	    for (const name of colours) {
51	      await expect(pdp.colourSwatch(name).locator('img')).toHaveAttribute('src', /.+/);
52	    }
53	  });
54	
55	  test('The colour currently being viewed is indicated as selected', TAGS, async ({ page }) => {
56	    const { sku } = pdpProductWithMultipleColours();
57	    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');
58	
59	    const pdp = new ProductPage(page);
60	    await pdp.goToProduct(sku);
61	
62	    // AC3 — exactly one swatch is selected on load, and the label agrees with it.
63	    await expect(pdp.selectedColourSwatch).toHaveCount(1);
64	    const selectedName = await pdp.selectedColourSwatch.getAttribute('aria-label');
65	    await expect(pdp.colourSelectedName).toHaveText(selectedName);
66	  });
67	
68	  test('Choosing a different colour updates the address bar without reloading the page', TAGS, async ({ page }) => {
69	    const { sku } = pdpProductWithMultipleColours();
70	    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');
71	
72	    const pdp = new ProductPage(page);
73	    await pdp.goToProduct(sku);
74	
75	    // Tag this document instance. A full reload would discard it — that is the assertion.
76	    await page.evaluate(() => {
77	      window.__sfcc91NoReload = true;
78	    });
79	
80	    const colours = await pdp.offeredColourNames();
81	    const selectedName = await pdp.selectedColourSwatch.getAttribute('aria-label');
82	    const target = colours.find((name) => name !== selectedName);
83	
84	    const targetValue = await pdp.colourValueFor(target);
85	    await pdp.selectColour(target);
86	
87	    // AC4 — the ?color= param carries the chosen colour's value, not merely *a* colour.
88	    // searchParams decodes for us, so this compares the real value even when encoded.
89	    await expect.poll(() => new URL(page.url()).searchParams.get('color')).toBe(targetValue);
90	    await expect(pdp.colourSwatch(target)).toHaveAttribute('aria-checked', 'true');
91	    // No full reload, and the product content never went away.
92	    expect(await page.evaluate(() => window.__sfcc91NoReload)).toBe(true);
93	    await expect(pdp.productName).toBeVisible();
94	  });
95	
96	  test('Choosing a different colour updates the colour label and the selected swatch', TAGS, async ({ page }) => {
97	    const { sku } = pdpProductWithMultipleColours();
98	    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');
99	
100	    const pdp = new ProductPage(page);
101	    await pdp.goToProduct(sku);
102	
103	    const colours = await pdp.offeredColourNames();
104	    const previousName = await pdp.selectedColourSwatch.getAttribute('aria-label');
105	    const target = colours.find((name) => name !== previousName);
106	
107	    await pdp.selectColour(target);
108	
109	    await expect(pdp.colourSelectedName).toHaveText(target);
110	    await expect(pdp.colourSwatch(target)).toHaveAttribute('aria-checked', 'true');
111	    await expect(pdp.colourSwatch(previousName)).toHaveAttribute('aria-checked', 'false');
112	    // Selection is single-valued throughout.
113	    await expect(pdp.selectedColourSwatch).toHaveCount(1);
114	  });
115	
116	  test('A colour variation with no image is not offered to the shopper', TAGS, async ({ page }) => {
117	    const { sku, withheldColourName } = pdpProductWithUnpopulatedColour();
118	    test.skip(!sku, 'No unpopulated-colour product SKU provisioned — set E2E_UNPOPULATED_COLOUR_PRODUCT_SKU.');
119	
120	    const pdp = new ProductPage(page);
121	    await pdp.goToProduct(sku);
122	
123	    // AC5 — the colour is absent from the group entirely, not rendered disabled.
124	    const colours = await pdp.offeredColourNames();
125	    expect(colours.length).toBeGreaterThan(1);
126	    if (withheldColourName) {
127	      // The load-bearing assertion: that specific colour is nowhere in the group.
128	      expect(colours).not.toContain(withheldColourName);
129	      await expect(pdp.colourSwatch(withheldColourName)).toHaveCount(0);
130	    }
131	    // Every swatch that IS offered has a real image behind it.
132	    for (const name of colours) {
133	      await expect(pdp.colourSwatch(name).locator('img')).toHaveAttribute('src', /.+/);
134	    }
135	  });
136	
137	  test('Opening a link that specifies a colour shows that colour as selected', TAGS, async ({ page }) => {
138	    const { sku } = pdpProductWithMultipleColours();
139	    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');
140	
141	    const pdp = new ProductPage(page);
142	    await pdp.goToProduct(sku);
143	
144	    // Pick a colour that is NOT the default, so the deep link proves something.
145	    const colours = await pdp.offeredColourNames();
146	    const defaultName = await pdp.selectedColourSwatch.getAttribute('aria-label');
147	    const target = colours.find((name) => name !== defaultName);
148	    await pdp.selectColour(target);
149	    const deepLink = page.url();
150	
151	    await page.goto(deepLink);
152	    await pdp.colourSwatchGroup.waitFor({ state: 'visible', timeout: 20000 });
153	
154	    await expect(pdp.colourSwatch(target)).toHaveAttribute('aria-checked', 'true');
155	    await expect(pdp.colourSelectedName).toHaveText(target);
156	  });
157	
158	  test('Colours can be chosen using only the keyboard', TAGS, async ({ page }) => {
159	    const { sku } = pdpProductWithMultipleColours();
160	    test.skip(!sku, 'No multi-colour product SKU provisioned — set E2E_MULTI_COLOUR_PRODUCT_SKU.');
161	
162	    const pdp = new ProductPage(page);
163	    await pdp.goToProduct(sku);
164	
165	    const startName = await pdp.selectedColourSwatch.getAttribute('aria-label');
166	    await pdp.focusColourSwatches();
167	    await page.keyboard.press('ArrowRight');
168	
169	    const nowName = await pdp.selectedColourSwatch.getAttribute('aria-label');
170	    expect(nowName).not.toBe(startName);
171	    await expect(pdp.colourSelectedName).toHaveText(nowName);
172	    // Focus follows selection, so the arrow keys stay usable without re-tabbing.
173	    await expect(pdp.colourSwatch(nowName)).toBeFocused();
174	  });
175	
176	  test('A colour that cannot be ordered is not offered to the shopper', TAGS, async ({ page }) => {
177	    const { sku, withheldColourName } = pdpProductWithNonOrderableColour();
178	    test.skip(!sku, 'No non-orderable-colour product SKU provisioned — set E2E_NON_ORDERABLE_COLOUR_PRODUCT_SKU.');
179	
180	    const pdp = new ProductPage(page);
181	    await pdp.goToProduct(sku);
182	
183	    // AC5 (BA clarification 2026-08-21) — an unavailable colour is withheld, not disabled.
184	    const colours = await pdp.offeredColourNames();
185	    expect(colours.length).toBeGreaterThan(1);
186	    if (withheldColourName) {
187	      // The load-bearing assertion. Without it this test passes even if the colour is
188	      // rendered, because a non-orderable colour can still have a perfectly good image.
189	      expect(colours).not.toContain(withheldColourName);
190	      await expect(pdp.colourSwatch(withheldColourName)).toHaveCount(0);
191	    }
192	    // Nothing in the group may advertise itself as disabled — there is no disabled state.
193	    await expect(pdp.colourSwatchGroup.locator('[aria-disabled="true"]')).toHaveCount(0);
194	    await expect(pdp.colourSwatchGroup.locator('[disabled]')).toHaveCount(0);
195	  });
196	
197	  test('A product whose colours are all unavailable shows no colour section at all', TAGS, async ({ page }) => {
198	    const { sku } = pdpProductWithAllColoursWithheld();
199	    test.skip(!sku, 'No all-withheld-colour product SKU provisioned — set E2E_ALL_WITHHELD_COLOUR_PRODUCT_SKU.');
200	
201	    const pdp = new ProductPage(page);
202	    await pdp.goToProduct(sku);
203	
204	    // The `hasOfferedColour` gate: colour data exists but nothing survives the AC5 filter,
205	    // so the whole block is suppressed — no bare "Colour:" label with nothing beside it.
206	    await expect(pdp.colourSection).toHaveCount(0);
207	    await expect(pdp.colourLabel).toHaveCount(0);
208	    await expect(pdp.colourSwatchGroup).toHaveCount(0);
209	    // The rest of the PDP is unaffected.
210	    await expect(pdp.productName).toBeVisible();
211	    await expect(pdp.productPrice).toBeVisible();
212	    await expect(pdp.productDescription).toBeVisible();
213	  });
214	
215	  test('Product information still displays when a product has no colour data', TAGS, async ({ page }) => {
216	    const { sku } = standardProduct();
